const LESSONS = {"en":{"foundations":{"title":"Stock Market Foundations","level":"beginner","time":"6 lessons","summary":"What a share is, how exchanges work, and how an order becomes a trade."},"investing":{"title":"Investing & Wealth Building","level":"beginner","time":"8 lessons","summary":"Set goals, understand your time horizon, diversify, and let compounding work over years."},"sip-mutual-funds":{"title":"SIP & Mutual Funds","level":"beginner","time":"7 lessons","summary":"How a Systematic Investment Plan works, what NAV means, and how to read fund costs."},"reading-charts":{"title":"Reading Charts","level":"beginner","time":"6 lessons","summary":"Understand line, bar and candlestick charts, OHLC data, and volume."},"fundamental-analysis":{"title":"Fundamental Analysis","level":"intermediate","time":"9 lessons","summary":"Evaluate a business using its financial statements, key ratios and quality checks.","sections":[{"h":"The three financial statements","ul":["Profit & loss: revenue, expenses and profit over a period.","Balance sheet: assets, liabilities and equity at one point in time.","Cash flow statement: the cash actually coming in and going out."]},{"h":"Key ratios","ul":["EPS (earnings per share) = net profit ÷ number of shares.","P/E ratio = share price ÷ EPS. A high P/E can reflect expected growth. Compare within the same industry.","ROE (return on equity) = net profit ÷ shareholders' equity. A consistently high ROE can signal an efficient business.","Debt-to-equity shows how much the company borrows relative to its equity."]},{"h":"Business quality and valuation","p":"Ratios are only a starting point. Study the business model, competitive advantage, management track record and governance. Annual reports and filings are public on exchange websites.","ul":["A low P/E can be a trap if earnings are falling.","Check whether profits are backed by real cash flow."]}]},"technical-analysis":{"title":"Technical Analysis","level":"intermediate","time":"10 lessons","summary":"Study price and volume patterns, trends, support, resistance and common indicators."},"swing-trading":{"title":"Swing Trading","level":"intermediate","time":"8 lessons","summary":"Hold trades for days to weeks using clear setups, entry and exit rules, and a trade journal."},"risk-management":{"title":"Risk Management","level":"intermediate","time":"7 lessons","summary":"Protect your capital with position sizing, stop losses, exposure limits and a drawdown plan."},"intraday-trading":{"title":"Intraday Trading","level":"advanced","time":"9 lessons","summary":"Trade within one session. Understand liquidity, order execution, margin and the real risks."},"futures-options":{"title":"Futures & Options","level":"advanced","time":"12 lessons","summary":"Understand futures, call and put options, strike price, expiry, margin and payoff, along with their risks."},"option-greeks":{"title":"Option Greeks & Strategies","level":"advanced","time":"10 lessons","summary":"Measure how option prices respond to price, time and volatility, and build defined-risk strategies."},"trading-psychology":{"title":"Trading Psychology","level":"advanced","time":"6 lessons","summary":"Recognise biases such as fear, greed and overtrading, and build a disciplined process."},"candlestick-patterns":{"title":"Candlestick and Chart Patterns","level":"intermediate","time":"25 patterns","summary":"Learn what each candle and chart shape signals, when it matters, how to confirm it, and the mistake to avoid."},"technical-indicators":{"title":"Technical Indicators","level":"intermediate","time":"10 indicators","summary":"Understand what moving averages, RSI, MACD, volume and other indicators measure, when to use each one, and how to use them in a trade."},"tax-basics":{"title":"Tax Basics for Indian Investors and Traders","level":"intermediate","time":"11 topics","summary":"How gains from shares, mutual funds, intraday and F&O are taxed in India, what records to keep, and where to verify the current rules."},"balance-sheet":{"title":"How to Read a Balance Sheet","level":"intermediate","time":"13 topics","summary":"What a balance sheet shows, how to read assets, liabilities and equity, and the ratios that reveal financial strength."},"cash-flow-statement":{"title":"How to Read a Cash Flow Statement","level":"intermediate","time":"13 topics","summary":"Where a company's real cash comes from and goes, and why cash flow can tell you more than profit."},"quarterly-results":{"title":"How to Read Quarterly Results","level":"intermediate","time":"13 topics","summary":"How to read the numbers in a quarterly results filing, compare them correctly, and spot one-off items."},"annual-report":{"title":"How to Read an Annual Report","level":"intermediate","time":"13 topics","summary":"The parts of a company's annual report, what each section tells you, and the warning signs to look for."},"shareholding-pattern":{"title":"Shareholding Pattern and Promoter Holding","level":"intermediate","time":"12 topics","summary":"Who owns a company, how promoter, institutional and public holdings change, and what pledged shares mean."},"valuation-basics":{"title":"Valuation Basics: What Is a Share Worth?","level":"advanced","time":"8 topics","summary":"P/E, P/B, EV/EBITDA, PEG and discounted cash flow explained, with their limits and how to combine them."},"corporate-actions":{"title":"Corporate Actions: Dividends, Bonus, Splits, Rights and Buybacks","level":"intermediate","time":"13 topics","summary":"What companies do with shares and cash, how each action changes the price and your holding, and how to avoid confusion on the ex-date."},"market-rules":{"title":"Market Rules & Investor Protection","level":"beginner","time":"10 topics","summary":"Market timings, settlement, price bands and circuit breakers, applying for IPOs, spotting scams and tips, and how to complain if something goes wrong."}},"hi":{"foundations":{"title":"शेयर बाज़ार की मूल बातें","level":"beginner","time":"6 पाठ","summary":"शेयर क्या है, एक्सचेंज कैसे काम करते हैं, और ऑर्डर ट्रेड में कैसे बदलता है।"},"investing":{"title":"निवेश और धन निर्माण","level":"beginner","time":"8 पाठ","summary":"लक्ष्य तय करें, समय-सीमा समझें, विविधीकरण करें और चक्रवृद्धि को वर्षों तक काम करने दें।"},"sip-mutual-funds":{"title":"SIP और म्यूचुअल फंड","level":"beginner","time":"7 पाठ","summary":"SIP कैसे काम करता है, NAV का मतलब क्या है, और फंड की लागत कैसे पढ़ें।"},"reading-charts":{"title":"चार्ट कैसे पढ़ें","level":"beginner","time":"6 पाठ","summary":"लाइन, बार और कैंडलस्टिक चार्ट, OHLC डेटा और वॉल्यूम समझें।"},"fundamental-analysis":{"title":"फंडामेंटल एनालिसिस","level":"intermediate","time":"9 पाठ","summary":"वित्तीय विवरण, प्रमुख अनुपात और गुणवत्ता जाँच से किसी कारोबार का मूल्यांकन करें।","sections":[{"h":"तीन मुख्य वित्तीय विवरण","ul":["प्रॉफ़िट एंड लॉस: एक अवधि की आय, खर्च और मुनाफ़ा।","बैलेंस शीट: किसी एक समय पर संपत्ति, देनदारी और इक्विटी।","कैश फ़्लो स्टेटमेंट: असल में कितना नकद आया और कितना गया।"]},{"h":"प्रमुख अनुपात","ul":["EPS (प्रति शेयर आय) = शुद्ध मुनाफ़ा ÷ शेयरों की संख्या।","P/E अनुपात = शेयर कीमत ÷ EPS। ऊँचा P/E अपेक्षित ग्रोथ दर्शा सकता है। उसी इंडस्ट्री से तुलना करें।","ROE (इक्विटी पर रिटर्न) = शुद्ध मुनाफ़ा ÷ शेयरधारक इक्विटी। लगातार ऊँचा ROE कुशल कारोबार का संकेत हो सकता है।","डेट-टू-इक्विटी बताता है कि कंपनी अपनी इक्विटी के मुकाबले कितना कर्ज़ लेती है।"]},{"h":"कारोबार की गुणवत्ता और मूल्यांकन","p":"अनुपात केवल शुरुआत हैं। बिज़नेस मॉडल, प्रतिस्पर्धी बढ़त, प्रबंधन का रिकॉर्ड और गवर्नेंस पढ़ें। सालाना रिपोर्ट और फ़ाइलिंग एक्सचेंज की वेबसाइट पर सार्वजनिक होती हैं।","ul":["कमाई घट रही हो तो कम P/E भी जाल हो सकता है।","देखें कि मुनाफ़े के पीछे असली कैश फ़्लो है या नहीं।"]}]},"technical-analysis":{"title":"टेक्निकल एनालिसिस","level":"intermediate","time":"10 पाठ","summary":"कीमत और वॉल्यूम पैटर्न, ट्रेंड, सपोर्ट, रेज़िस्टेंस और आम इंडिकेटर पढ़ें।"},"swing-trading":{"title":"स्विंग ट्रेडिंग","level":"intermediate","time":"8 पाठ","summary":"साफ़ सेटअप, एंट्री-एग्ज़िट नियम और ट्रेड जर्नल से कुछ दिनों से कुछ हफ़्तों तक ट्रेड रखें।"},"risk-management":{"title":"जोखिम प्रबंधन","level":"intermediate","time":"7 पाठ","summary":"पोज़िशन साइज़, स्टॉप लॉस, एक्सपोज़र सीमा और ड्रॉडाउन योजना से पूँजी की रक्षा करें।"},"intraday-trading":{"title":"इंट्राडे ट्रेडिंग","level":"advanced","time":"9 पाठ","summary":"एक ही सत्र में ट्रेड करें। लिक्विडिटी, ऑर्डर निष्पादन, मार्जिन और असली जोखिम समझें।"},"futures-options":{"title":"फ्यूचर्स और ऑप्शंस (F&O)","level":"advanced","time":"12 पाठ","summary":"फ्यूचर्स, कॉल और पुट ऑप्शंस, स्ट्राइक, एक्सपायरी, मार्जिन और पेऑफ़ को उनके जोखिमों के साथ समझें।"},"option-greeks":{"title":"ऑप्शन ग्रीक्स और रणनीतियाँ","level":"advanced","time":"10 पाठ","summary":"कीमत, समय और अस्थिरता के साथ ऑप्शन की कीमत कैसे बदलती है, यह समझें और सीमित-जोखिम रणनीतियाँ बनाएँ।"},"trading-psychology":{"title":"ट्रेडिंग मनोविज्ञान","level":"advanced","time":"6 पाठ","summary":"डर, लालच और ओवरट्रेडिंग जैसे पूर्वाग्रह पहचानें और अनुशासित प्रक्रिया बनाएँ।"},"candlestick-patterns":{"title":"कैंडलस्टिक और चार्ट पैटर्न","level":"intermediate","time":"25 पैटर्न","summary":"हर कैंडल और चार्ट आकार का संकेत, उसका महत्व, पुष्टि कैसे करें, और कौन सी गलती से बचें, यह सीखें।"},"technical-indicators":{"title":"टेक्निकल इंडिकेटर","level":"intermediate","time":"10 इंडिकेटर","summary":"मूविंग एवरेज, RSI, MACD, वॉल्यूम और अन्य इंडिकेटर क्या मापते हैं, हर एक कब इस्तेमाल करें, और ट्रेड में कैसे इस्तेमाल करें, यह समझें।"},"tax-basics":{"title":"भारतीय निवेशकों और ट्रेडरों के लिए टैक्स बेसिक्स","level":"intermediate","time":"11 विषय","summary":"भारत में शेयर, म्यूचुअल फंड, इंट्राडे और F&O से होने वाले लाभ पर टैक्स कैसे लगता है, कौन से रिकॉर्ड रखें, और मौजूदा नियम कहाँ जाँचें।"},"balance-sheet":{"title":"बैलेंस शीट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"बैलेंस शीट क्या दिखाती है, संपत्ति, देनदारी और इक्विटी कैसे पढ़ें, और वित्तीय मज़बूती बताने वाले अनुपात।"},"cash-flow-statement":{"title":"कैश फ़्लो स्टेटमेंट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी का असली नकद कहाँ से आता और कहाँ जाता है, और कैश फ़्लो मुनाफ़े से ज़्यादा क्या बताता है।"},"quarterly-results":{"title":"तिमाही नतीजे कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"तिमाही नतीजों के आँकड़े कैसे पढ़ें, सही तुलना कैसे करें, और एक-बार की मदों को कैसे पहचानें।"},"annual-report":{"title":"सालाना रिपोर्ट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी की सालाना रिपोर्ट के हिस्से, हर हिस्सा क्या बताता है, और चेतावनी के संकेत।"},"shareholding-pattern":{"title":"शेयरहोल्डिंग पैटर्न और प्रमोटर होल्डिंग","level":"intermediate","time":"12 विषय","summary":"कंपनी का मालिक कौन है, प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग कैसे बदलती है, और गिरवी शेयरों का क्या मतलब है।"},"valuation-basics":{"title":"वैल्यूएशन की मूल बातें: शेयर की क़ीमत क्या होनी चाहिए?","level":"advanced","time":"8 विषय","summary":"P/E, P/B, EV/EBITDA, PEG और डिस्काउंटेड कैश फ़्लो समझाए गए, उनकी सीमाओं के साथ और उन्हें मिलाकर कैसे इस्तेमाल करें।"},"corporate-actions":{"title":"कॉर्पोरेट एक्शन: डिविडेंड, बोनस, स्प्लिट, राइट्स और बायबैक","level":"intermediate","time":"13 विषय","summary":"कंपनियाँ शेयर और नकद के साथ क्या करती हैं, हर एक्शन कीमत और आपकी होल्डिंग को कैसे बदलता है, और एक्स-डेट पर भ्रम से कैसे बचें।"},"market-rules":{"title":"बाज़ार के नियम और निवेशक सुरक्षा","level":"beginner","time":"10 विषय","summary":"बाज़ार का समय, सेटलमेंट, प्राइस बैंड और सर्किट ब्रेकर, IPO में आवेदन, धोखाधड़ी और टिप्स पहचानना, और कुछ गलत होने पर शिकायत कैसे करें।"}}};
const LESSON_OVERRIDES = {"en":{"fundamental-analysis":{"sections":[{"h":"1. What fundamental analysis is","p":"Fundamental analysis asks whether a business is worth its price. It looks at the company's sales, profits, debts, cash, management and industry. The goal is to estimate what the business is worth and compare that with the share price. The gap between the two is the margin of safety that value investors look for."},{"h":"2. Where to find the information","ul":["Annual report: the full picture, including management discussion, risks and audited financial statements.","Quarterly results: the latest profit, sales and sometimes cash flow. Filed on the exchange websites (NSE and BSE).","Investor presentations and earnings calls: management's explanation of the numbers.","Shareholding pattern: promoter, institutional and public holdings, filed every quarter.","Corporate announcements: dividends, bonus issues, board decisions and material events."]},{"h":"3. The three financial statements","p":"A company's story is told in three statements that must be read together.","ul":["Profit and loss statement: revenue, expenses and profit over a period. Shows whether the business earns money.","Balance sheet: assets, liabilities and equity at one date. Shows what the company owns and owes.","Cash flow statement: cash from operations, investing and financing. Shows whether profits become real cash."],"p2":"A company can show a profit and still run out of cash. Always check whether operating cash flow is close to net profit over several years."},{"h":"4. Core ratios with formulas and an example","ul":["EPS (earnings per share) = net profit ÷ number of shares. Example: ₹300 crore profit ÷ 10 crore shares = ₹30 EPS.","P/E ratio = share price ÷ EPS. Example: ₹450 ÷ ₹30 = 15 times earnings.","ROE (return on equity) = net profit ÷ shareholders' equity. Example: ₹500 crore ÷ ₹2,500 crore = 20%.","Debt-to-equity = total debt ÷ shareholders' equity. Example: ₹1,000 crore ÷ ₹2,500 crore = 0.4.","Dividend yield = dividend per share ÷ share price. Example: ₹10 ÷ ₹450 ≈ 2.2%.","Operating margin = operating profit ÷ revenue. Shows how much each rupee of sales keeps after running costs."]},{"h":"5. Growth: is the company getting bigger and better?","p":"A good business grows its sales and profits over time, and does so without needing ever more debt. Look at 5 to 10 years of data, not one quarter. Check whether revenue growth comes with stable or improving margins, and whether the return on capital stays high as the company expands."},{"h":"6. Quality: the business behind the numbers","p":"Ratios cannot tell you everything. Quality questions include: Does the company have a durable advantage, such as a brand, cost position, network or regulatory licence? Is management honest and competent, with a record of allocating capital well? Are related-party transactions or accounting changes a concern? Is the business easy to understand?"},{"h":"7. Valuation: how much is it worth?","p":"Valuation estimates what the business is worth per share, using methods such as comparing P/E with peers, comparing price-to-book, or estimating future cash flows discounted to today. No method gives a single correct answer. Use two or three approaches to get a range, and buy only when the price is comfortably below your estimate.","ul":["Relative valuation: compare P/E, price-to-book and EV/EBITDA with similar companies.","Absolute valuation (discounted cash flow): estimate future cash flows and discount them. Very sensitive to assumptions.","A cheap-looking stock can be a value trap if earnings are falling. A high-priced stock can still be good if growth is strong and durable."]},{"h":"8. A worked example","p":"Company X: price ₹450, EPS ₹30 (P/E 15), ROE 20%, debt-to-equity 0.4, sales growing 15% a year for five years, operating margin steady at 18%. Peers trade at an average P/E of 20. Company X looks reasonable on these figures: strong returns, low debt and a P/E below peers. Before deciding, check the annual report for one-off profits, the quality of cash flow and the risks listed by management. The example is illustrative, not a recommendation."},{"h":"9. Red flags to check every time","ul":["Profits rising while operating cash flow falls for several years.","Receivables growing much faster than sales.","Frequent changes in auditors or accounting policies.","Promoter shares being pledged in large amounts.","Heavy reliance on one customer, one product or one government contract.","Management that changes its targets or explanations often."]},{"h":"10. Building your own process","p":"Write a one-page checklist: business model, growth, margins, returns, debt, cash flow, management, valuation, and risks. Fill it in from the annual report before you read any opinion. Review your holdings when results come out, not every day. Your job is to understand the business well enough to explain why you own it, and to know what would make you sell."}]}},"hi":{"fundamental-analysis":{"sections":[{"h":"1. फंडामेंटल एनालिसिस क्या है","p":"फंडामेंटल एनालिसिस यह पूछता है कि कारोबार अपनी कीमत के लायक है या नहीं। यह कंपनी की बिक्री, मुनाफ़ा, कर्ज़, नकदी, प्रबंधन और उद्योग देखता है। लक्ष्य है यह अनुमान लगाना कि कारोबार की वैल्यू क्या है और उसकी तुलना शेयर कीमत से करना। दोनों के बीच का अंतर वह सुरक्षा मार्जिन है जिसे वैल्यू निवेशक खोजते हैं।"},{"h":"2. जानकारी कहाँ मिलेगी","ul":["सालाना रिपोर्ट: पूरी तस्वीर, जिसमें प्रबंधन की चर्चा, जोखिम और ऑडिटेड वित्तीय विवरण।","तिमाही नतीजे: ताज़ा मुनाफ़ा, बिक्री और कभी-कभी कैश फ़्लो। NSE और BSE की वेबसाइट पर दाखिल।","निवेशक प्रस्तुति और अर्निंग कॉल: संख्याओं की प्रबंधन द्वारा व्याख्या।","शेयरहोल्डिंग पैटर्न: प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग, हर तिमाही दाखिल।","कॉर्पोरेट घोषणाएँ: डिविडेंड, बोनस इश्यू, बोर्ड के फ़ैसले और महत्वपूर्ण घटनाएँ।"]},{"h":"3. तीन वित्तीय विवरण","p":"कंपनी की कहानी तीन विवरणों में होती है, जिन्हें एक साथ पढ़ना होता है।","ul":["प्रॉफ़िट और लॉस स्टेटमेंट: एक अवधि की आय, खर्च और मुनाफ़ा। दिखाता है कि कारोबार पैसा कमाता है या नहीं।","बैलेंस शीट: एक तारीख़ पर संपत्ति, देनदारी और इक्विटी। दिखाता है कंपनी का क्या है और क्या बकाया।","कैश फ़्लो स्टेटमेंट: संचालन, निवेश और वित्तपोषण से नकद। दिखाता है कि मुनाफ़ा असली नकद बनता है या नहीं।"],"p2":"कंपनी मुनाफ़ा दिखाकर भी नकदी ख़त्म होने की स्थिति में हो सकती है। कई सालों में देखें कि संचालन कैश फ़्लो शुद्ध मुनाफ़े के आसपास है या नहीं।"},{"h":"4. सूत्र और उदाहरण के साथ मुख्य अनुपात","ul":["EPS (प्रति शेयर आय) = शुद्ध मुनाफ़ा ÷ शेयरों की संख्या। उदाहरण: ₹300 करोड़ मुनाफ़ा ÷ 10 करोड़ शेयर = ₹30 EPS।","P/E अनुपात = शेयर कीमत ÷ EPS। उदाहरण: ₹450 ÷ ₹30 = कमाई का 15 गुना।","ROE (इक्विटी पर रिटर्न) = शुद्ध मुनाफ़ा ÷ शेयरधारक इक्विटी। उदाहरण: ₹500 करोड़ ÷ ₹2,500 करोड़ = 20%।","डेट-टू-इक्विटी = कुल कर्ज़ ÷ शेयरधारक इक्विटी। उदाहरण: ₹1,000 करोड़ ÷ ₹2,500 करोड़ = 0.4।","डिविडेंड यील्ड = प्रति शेयर डिविडेंड ÷ शेयर कीमत। उदाहरण: ₹10 ÷ ₹450 ≈ 2.2%।","ऑपरेटिंग मार्जिन = ऑपरेटिंग मुनाफ़ा ÷ राजस्व। दिखाता है कि हर रुपये की बिक्री से चालू खर्च के बाद कितना बचता है।"]},{"h":"5. ग्रोथ: क्या कंपनी बड़ी और बेहतर हो रही है?","p":"अच्छा कारोबार समय के साथ बिक्री और मुनाफ़ा बढ़ाता है, और बिना ज़्यादा कर्ज़ के। एक तिमाही नहीं, 5 से 10 साल का डेटा देखें। जाँचें कि राजस्व वृद्धि के साथ मार्जिन स्थिर या बेहतर है या नहीं, और कंपनी बढ़ते हुए भी पूँजी पर रिटर्न ऊँचा रहता है या नहीं।"},{"h":"6. गुणवत्ता: संख्याओं के पीछे का कारोबार","p":"अनुपात सब कुछ नहीं बता सकते। गुणवत्ता के सवाल: क्या कंपनी के पास टिकाऊ बढ़त है, जैसे ब्रांड, लागत की स्थिति, नेटवर्क या नियामक लाइसेंस? क्या प्रबंधन ईमानदार और सक्षम है, और पूँजी का अच्छा उपयोग करने का रिकॉर्ड है? क्या संबंधित-पक्ष लेनदेन या लेखांकन बदलाव चिंता की बात हैं? क्या कारोबार आसानी से समझ आता है?"},{"h":"7. मूल्यांकन: यह कितने की है?","p":"मूल्यांकन अनुमान लगाता है कि कारोबार की प्रति शेयर वैल्यू क्या है, जैसे P/E की साथी कंपनियों से तुलना, प्राइस-टू-बुक, या भविष्य के कैश फ़्लो को आज की वैल्यू पर लाना। कोई एक तरीका सही उत्तर नहीं देता। दो-तीन तरीके इस्तेमाल करके एक रेंज लें, और तभी ख़रीदें जब कीमत आपके अनुमान से आराम से नीचे हो।","ul":["सापेक्ष मूल्यांकन: P/E, प्राइस-टू-बुक और EV/EBITDA की समान कंपनियों से तुलना।","पूर्ण मूल्यांकन (डिस्काउंटेड कैश फ़्लो): भविष्य के कैश फ़्लो का अनुमान और उसका वर्तमान मूल्य। धारणाओं पर बहुत निर्भर।","सस्ता दिखने वाला शेयर वैल्यू ट्रैप हो सकता है यदि कमाई गिर रही हो। ऊँची कीमत वाला शेयर भी अच्छा हो सकता है यदि ग्रोथ मज़बूत और टिकाऊ हो।"]},{"h":"8. एक काम किया हुआ उदाहरण","p":"कंपनी X: कीमत ₹450, EPS ₹30 (P/E 15), ROE 20%, डेट-टू-इक्विटी 0.4, बिक्री पाँच साल से 15% सालाना बढ़ रही है, ऑपरेटिंग मार्जिन 18% स्थिर। साथी कंपनियों का औसत P/E 20 है। इन आँकड़ों पर X उचित लगती है: मज़बूत रिटर्न, कम कर्ज़ और साथियों से कम P/E। फ़ैसले से पहले सालाना रिपोर्ट में एक-बार के मुनाफ़े, कैश फ़्लो की गुणवत्ता और प्रबंधन के बताए जोखिम जाँचें। यह उदाहरण है, सिफ़ारिश नहीं।"},{"h":"9. हर बार जाँचे जाने वाले लाल झंडे","ul":["मुनाफ़ा बढ़ता रहे पर संचालन कैश फ़्लो कई सालों से गिरे।","रिसीवेबल्स बिक्री से कहीं तेज़ बढ़ें।","बार-बार ऑडिटर या लेखांकन नीतियाँ बदलें।","प्रमोटर के शेयर बड़ी मात्रा में गिरवी (प्लेज़) हों।","एक ग्राहक, एक उत्पाद या एक सरकारी अनुबंध पर भारी निर्भरता।","प्रबंधन बार-बार लक्ष्य या स्पष्टीकरण बदले।"]},{"h":"10. अपनी प्रक्रिया बनाना","p":"एक पन्ने की चेकलिस्ट लिखें: कारोबार मॉडल, ग्रोथ, मार्जिन, रिटर्न, कर्ज़, कैश फ़्लो, प्रबंधन, मूल्यांकन और जोखिम। किसी राय को पढ़ने से पहले सालाना रिपोर्ट से भरें। नतीजे आने पर होल्डिंग की समीक्षा करें, हर दिन नहीं। आपका काम कारोबार को इतना समझना है कि आप बता सकें कि आपने उसे क्यों रखा है, और किस बात पर बेचेंगे।"}]}}};
const LESSON_EXTRAS_EN = {"fundamental-analysis":{"examples":[{"title":"P/E and earnings growth","text":"A stock trades at ₹300 with EPS of ₹15, so P/E = 20. If EPS rises 20% to ₹18 and the price stays at ₹300, P/E falls to 16.7. Higher earnings can make a stock look cheaper even at the same price."},{"title":"Return on equity","text":"Net profit ₹500 crore on shareholders' equity of ₹2,500 crore gives ROE = 500 ÷ 2,500 = 20%. Debt of ₹1,000 crore against that equity gives debt-to-equity = 1,000 ÷ 2,500 = 0.4."}],"scenarios":[{"title":"Profit rises but cash flow is negative","text":"The company reports higher profit, but operating cash flow is negative and receivables grow faster than sales. This can mean customers are not paying. Profit that never turns into cash is a warning sign."},{"title":"Cheap stock in a shrinking industry","text":"A stock has a P/E of 6, far below its peers. Its industry is losing demand and earnings are falling each year. A low P/E here may be a value trap, not a bargain."}],"useCases":["Screening for companies with consistent ROE above a chosen level over five years.","Comparing two companies in the same industry using P/E, margins and debt levels.","Reading the annual report before results to understand management's plans and risks."],"takeaways":["Read the three statements together; one statement alone can mislead.","P/E only makes sense relative to growth, risk and industry peers.","Check whether profit converts to cash flow.","Ratios start the research; business quality and management decide the conclusion."],"practice":[{"q":"A stock trades at ₹450 with EPS of ₹30. What is its P/E?","a":"450 ÷ 30 = 15."},{"q":"Why compare P/E ratios within the same industry?","a":"Different industries have different growth rates, margins and capital needs, so their normal P/E levels differ."},{"q":"Receivables are rising faster than sales. Is this a positive or negative sign?","a":"Usually negative. It can mean customers are slow to pay, or revenue is being recognised aggressively. Investigate before investing."}]}};
const LESSON_EXTRAS_HI = {"fundamental-analysis":{"examples":[{"title":"P/E और कमाई की वृद्धि","text":"शेयर ₹300 पर है और EPS ₹15 है, तो P/E = 20। अगर EPS 20% बढ़कर ₹18 हो जाए और कीमत ₹300 ही रहे, तो P/E घटकर 16.7 हो जाता है। एक ही कीमत पर ज़्यादा कमाई शेयर को सस्ता दिखा सकती है।"},{"title":"इक्विटी पर रिटर्न","text":"शुद्ध मुनाफ़ा ₹500 करोड़ और शेयरधारक इक्विटी ₹2,500 करोड़ से ROE = 500 ÷ 2,500 = 20%। उसी इक्विटी पर ₹1,000 करोड़ का कर्ज़ हो, तो डेट-टू-इक्विटी = 1,000 ÷ 2,500 = 0.4।"}],"scenarios":[{"title":"मुनाफ़ा बढ़ा, पर कैश फ़्लो नेगेटिव","text":"कंपनी ज़्यादा मुनाफ़ा दिखाती है, पर ऑपरेटिंग कैश फ़्लो नेगेटिव है और रिसीवेबल्स बिक्री से तेज़ बढ़ रहे हैं। इसका मतलब हो सकता है कि ग्राहक भुगतान नहीं कर रहे। ऐसा मुनाफ़ा जो कभी नकद नहीं बनता, चेतावनी है।"},{"title":"घटते उद्योग का सस्ता शेयर","text":"एक शेयर का P/E 6 है, जो अपने साथियों से काफ़ी कम है। उसके उद्योग की माँग घट रही है और कमाई हर साल गिर रही है। यहाँ कम P/E सौदा नहीं, बल्कि वैल्यू ट्रैप हो सकता है।"}],"useCases":["पाँच साल तक लगातार ऊँचे ROE वाली कंपनियों को स्क्रीन करना।","एक ही उद्योग की दो कंपनियों की P/E, मार्जिन और कर्ज़ के स्तर से तुलना।","नतीजों से पहले सालाना रिपोर्ट पढ़कर प्रबंधन की योजनाएँ और जोखिम समझना।"],"takeaways":["तीनों विवरण साथ पढ़ें; अकेला विवरण गुमराह कर सकता है।","P/E तभी अर्थपूर्ण है जब उसे ग्रोथ, जोखिम और साथी कंपनियों के साथ देखा जाए।","देखें कि मुनाफ़ा कैश फ़्लो में बदल रहा है या नहीं।","अनुपात शोध की शुरुआत हैं; निष्कर्ष कारोबार की गुणवत्ता और प्रबंधन तय करते हैं।"],"practice":[{"q":"शेयर ₹450 पर है और EPS ₹30 है। P/E क्या है?","a":"450 ÷ 30 = 15।"},{"q":"P/E की तुलना एक ही उद्योग में क्यों करें?","a":"अलग उद्योगों की ग्रोथ, मार्जिन और पूँजी ज़रूरतें अलग होती हैं, इसलिए उनका सामान्य P/E स्तर भी अलग होता है।"},{"q":"रिसीवेबल्स बिक्री से तेज़ बढ़ रहे हैं। यह सकारात्मक संकेत है या नकारात्मक?","a":"आमतौर पर नकारात्मक। इसका मतलब ग्राहक देर से भुगतान कर रहे हैं, या राजस्व आक्रामक तरीके से दर्ज हो रहा है। निवेश से पहले जाँच करें।"}]}};
