const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Market capitalisation (market cap)","hi":"मार्केट कैप"},"def":{"en":"Share price multiplied by the number of shares outstanding. Companies are grouped as large, mid or small cap.","hi":"शेयर कीमत को बकाया शेयरों की संख्या से गुणा करने पर मिलने वाली कंपनी की कुल वैल्यू। कंपनियाँ लार्ज, मिड या स्मॉल कैप में बाँटी जाती हैं।"}},{"cat":"fundamental","term":{"en":"EPS (earnings per share)","hi":"EPS (प्रति शेयर आय)"},"def":{"en":"Net profit divided by the number of shares outstanding.","hi":"शुद्ध मुनाफ़े को बकाया शेयरों की संख्या से भाग देने पर प्राप्त राशि।"}},{"cat":"fundamental","term":{"en":"P/E ratio","hi":"P/E अनुपात"},"def":{"en":"Share price divided by earnings per share. It shows how much investors pay for each rupee of earnings.","hi":"शेयर कीमत को EPS से भाग देने पर प्राप्त अनुपात। यह दिखाता है कि निवेशक कमाई के हर रुपये के लिए कितना दे रहे हैं।"}},{"cat":"fundamental","term":{"en":"Book value","hi":"बुक वैल्यू"},"def":{"en":"Shareholders' equity divided by the number of shares: the accounting value per share.","hi":"शेयरधारक इक्विटी को शेयरों की संख्या से भाग देने पर प्रति शेयर लेखांकन मूल्य।"}},{"cat":"fundamental","term":{"en":"ROE (return on equity)","hi":"ROE (इक्विटी पर रिटर्न)"},"def":{"en":"Net profit divided by shareholders' equity. It shows how well the company uses shareholder money.","hi":"शुद्ध मुनाफ़े को शेयरधारक इक्विटी से भाग देने पर प्राप्त अनुपात। यह दिखाता है कि कंपनी शेयरधारकों के पैसे का कितना अच्छा उपयोग करती है।"}},{"cat":"fundamental","term":{"en":"Debt-to-equity","hi":"डेट-टू-इक्विटी"},"def":{"en":"Total debt divided by shareholders' equity. Higher values mean more borrowing.","hi":"कुल कर्ज़ को शेयरधारक इक्विटी से भाग देने पर प्राप्त अनुपात। ज़्यादा मान का मतलब ज़्यादा उधारी।"}},{"cat":"fundamental","term":{"en":"Dividend yield","hi":"डिविडेंड यील्ड"},"def":{"en":"Annual dividend per share divided by share price, shown as a percentage.","hi":"प्रति शेयर सालाना डिविडेंड को शेयर कीमत से भाग देने पर प्रतिशत।"}},{"cat":"fundamental","term":{"en":"Revenue (sales)","hi":"राजस्व (बिक्री)"},"def":{"en":"Total income from selling goods or services before any costs are deducted.","hi":"कोई भी खर्च घटाने से पहले सामान या सेवाएँ बेचकर कुल आय।"}},{"cat":"fundamental","term":{"en":"Net profit","hi":"शुद्ध मुनाफ़ा"},"def":{"en":"What is left from revenue after all costs, interest and taxes are paid.","hi":"सभी खर्च, ब्याज और टैक्स चुकाने के बाद राजस्व में जो बचता है।"}},{"cat":"fundamental","term":{"en":"Balance sheet","hi":"बैलेंस शीट"},"def":{"en":"A statement of assets, liabilities and equity at one point in time.","hi":"किसी एक समय पर संपत्ति, देनदारी और इक्विटी का विवरण।"}},{"cat":"fundamental","term":{"en":"Cash flow statement","hi":"कैश फ़्लो स्टेटमेंट"},"def":{"en":"A record of the actual cash coming in and going out, from operations, investing and financing.","hi":"संचालन, निवेश और वित्तपोषण से वास्तव में आने और जाने वाले नकद का विवरण।"}},{"cat":"fundamental","term":{"en":"Annual report","hi":"वार्षिक रिपोर्ट"},"def":{"en":"A yearly document from a company with financial statements, management discussion and risks.","hi":"कंपनी का सालाना दस्तावेज़, जिसमें वित्तीय विवरण, प्रबंधन की चर्चा और जोखिम होते हैं।"}}];
